// EB Games Australia shop assortment (reference mode).
// A browsing shelf modelled on the real ebgames.com.au range on 2026-10-13: games, consoles,
// accessories, trading cards, Pop! Vinyls and collectibles, EB exclusive clothing, homewares,
// toys, board games, books and movies. Prices are AUD (GST inclusive) and follow the real site's
// price points. These are ordinary retail products: they are kept apart from the evidence-backed
// Grand Theft Auto VI listings (canonical-products.js) and are never recorded as GTA game lines.

const slugify = s => s.toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '').replace(/&/g, ' and ').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 80)
const hash = s => { let n = 2166136261; for (const c of String(s)) n = Math.imul(n ^ c.codePointAt(0), 16777619); return n >>> 0 }

const PLATFORM_SLUG = { 'PlayStation 5': 'ps5', 'PlayStation 4': 'ps4', 'PlayStation 3': 'ps3', 'PlayStation 2': 'ps2', 'Xbox Series X': 'xbox-series-x', 'Xbox One': 'xbox-one', 'Xbox 360': 'xbox-360', 'Nintendo Switch 2': 'nintendo-switch-2', 'Nintendo Switch': 'nintendo-switch', 'Nintendo 3DS': 'nintendo-3ds', PC: 'pc' }
const SHORT = { 'PlayStation 5': 'PS5', 'PlayStation 4': 'PS4', 'Xbox Series X': 'Xbox Series X', 'Nintendo Switch 2': 'Switch 2', 'Nintendo Switch': 'Switch' }
const CATEGORY_SLUG = { 'Trading Cards': 'trading-cards', Collectibles: 'toys-and-collectibles', Clothing: 'clothing', Homewares: 'homewares', 'Toys & Games': 'toys-and-collectibles', 'Books & Comics': 'books', 'Movies & TV': 'movies-tv', 'Digital Currency & Gift Cards': 'digital' }

export const SHELF = []
function add(sku, title, price, category, type, brand, specs, extra = {}) {
  const h = hash(sku)
  const platform = extra.platform || 'All platforms'
  const slugBase = PLATFORM_SLUG[platform] && ['Video Games', 'Consoles', 'Gaming Accessories'].includes(category) ? PLATFORM_SLUG[platform] : extra.loot ? 'loot' : CATEGORY_SLUG[category] || 'accessories'
  const reviews = extra.preorder ? 0 : extra.reviews ?? (h % 7 === 0 ? 0 : 3 + h % 240)
  const p = {
    sku, title, price, category, type, brand, specs, shelf: true,
    platform, condition: 'New', stock: 5 + h % 20, delivery: true, pickup: true,
    rating: reviews ? Math.round((3.9 + (h % 11) / 10) * 10) / 10 : 0, reviews,
    release: '2026-06-01', keywords: '', sub: '', attrs: [],
    ...extra,
  }
  if (p.rating > 5) p.rating = 5
  p.path = `/product/${slugBase}/${sku}-${slugify(title)}`
  p.description = extra.description || `${title}. ${Object.entries(specs).map(([k, v]) => `${k}: ${v}`).join('. ')}.`
  SHELF.push(p)
  return p
}

// ---------- Video games ----------
const RATING = { G: 'G', PG: 'PG', M: 'M', MA: 'MA15+', R: 'R18+' }
function game(sku, name, platform, price, rating, genre, publisher, extra = {}) {
  const preowned = extra.condition === 'Preowned'
  const format = /code.in.a.box/i.test(name) ? 'Code in box' : ['Nintendo Switch', 'Nintendo Switch 2', 'Nintendo 3DS'].includes(platform) ? 'Game card' : platform === 'PC' ? 'Digital code in box' : 'Physical disc'
  const title = `${name}${extra.noPlatformInTitle ? '' : ` - ${platform}`}`
  return add(sku, title, price, 'Video Games', 'game', publisher, { Platform: platform, Genre: genre, Classification: RATING[rating] || rating, Format: format, Publisher: publisher, ...(preowned ? { Condition: 'Preowned - tested and cleaned' } : {}) },
    { platform, catalogType: 'game', release: extra.release || '2025-11-01', keywords: `${SHORT[platform] || ''} ${genre} ${extra.keywords || ''}`.toLowerCase(), sub: 'gaming-video-game', ...extra })
}
const PS5 = 'PlayStation 5', PS4 = 'PlayStation 4', XSX = 'Xbox Series X', XB1 = 'Xbox One', NS2 = 'Nintendo Switch 2', NS = 'Nintendo Switch', PC = 'PC'

