const SIZES = (price, stock = [3, 6, 6, 4, 2]) => ['S', 'M', 'L', 'XL', '2XL'].map((label, i) => ({ id: label.toLowerCase(), label, price, stock: stock[i] }))
const KIDS = price => ['8', '10', '12', '14'].map((label, i) => ({ id: `kids-${label}`, label: `Kids ${label}`, price, stock: [2, 4, 3, 2][i] }))
