// Illustration hints for the local product artwork renderer (lib/product-asset-art.js), so each
// card shows the actual kind of item (a Pop! Vinyl is a figure, not a record; an Elite Trainer
// Box is a card box, not a shoe). Hardware and games use their own titles.
const ART = {
  cards: p => /box|bundle|tin|collection|trove|blister|kit/i.test(p.title) ? 'Trading card box' : 'Trading card booster pack',
  giftcard: () => 'Gift card', binder: () => 'Card binder', sleeves: p => /toploader/i.test(p.title) ? 'Deck box' : 'Card sleeves', case: p => p.category === 'Trading Cards' ? 'Deck box' : null,
  figure: p => /plush/i.test(p.title) ? 'Plush toy' : 'Collector figure', statue: () => 'Collector figure', replica: () => 'Collector figure', keyring: () => 'keychain',
  shirt: () => 'T-shirt', jersey: () => 'Jersey', shorts: () => 'Shorts', socks: () => 'Socks', hoodie: () => 'Hoodie', pyjamas: () => 'Long-sleeve shirt',
  cap: () => 'Cap', beanie: () => 'Beanie', slippers: () => 'Slipper shoes', cosplay: () => 'Bandana', accessory: () => 'Enamel pins', bag: () => 'Backpack', wallet: () => 'Wallet',
  pet: p => /collar/i.test(p.title) ? 'Pet collar' : 'Plush dog toy',
  mug: () => 'Mug', glass: () => 'Glass tumbler', bottle: () => 'Flask', candle: () => 'Candle', doormat: () => 'Rug', towel: () => 'Towel', blanket: () => 'Blanket', bedding: () => 'Quilt cover', cushion: () => 'Cushion',
  notebook: () => 'Notebook', poster: () => 'Poster', 'pencil-case': () => 'Pouch', book: () => 'Book',
  plush: () => 'Plush toy', bricks: () => 'Building set', board: p => /puzzle/i.test(p.title) ? 'Jigsaw puzzle' : 'Board game', beyblade: () => 'Spinning top toy', blaster: () => 'Toy blaster', electronic: () => 'Electronic toy', toy: () => 'Toy',
}
for (const p of SHELF) p.artHint = ART[p.type]?.(p) || null

export const SHELF_DEPARTMENTS =['Video Games', 'Consoles', 'Gaming Accessories', 'Digital Currency & Gift Cards', 'Trading Cards', 'Collectibles', 'Clothing', 'Homewares', 'Toys & Games', 'Books & Comics', 'Movies & TV']
